'@
        $out = New-BuildMatrix -Config ($json | ConvertFrom-Json)
        $out.'max-parallel' | Should -Be 7
        $out.'fail-fast'    | Should -Be $false
        $out.'max-size'     | Should -Be 9
    }
}

Describe 'New-BuildMatrix - validation and error handling' {
